36: /**
37:  * A handler that executes {@link HealthCheck health checks} and renders the results.
38:  * <p>
39:  * The handler obtains health checks via the context's registry.
40:  * Typically, health checks are added to the server registry.
41:  * <pre class="java">{@code
42:  * import ratpack.exec.Promise;
43:  * import ratpack.registry.Registry;
44:  * import ratpack.health.HealthCheck;
45:  * import ratpack.health.HealthCheckHandler;
46:  * import ratpack.test.embed.EmbeddedApp;
47:  *
48:  * import static org.junit.Assert.*;
49:  *
50:  * public class Example {
51:  *
52:  *   static class ExampleHealthCheck implements HealthCheck {
53:  *     public String getName() {
54:  *       return "example"; // must be unique within the application
55:  *     }
56:  *
57:  *     public Promise<HealthCheck.Result> check(Registry registry) throws Exception {
58:  *       return Promise.value(HealthCheck.Result.healthy());
59:  *     }
60:  *   }
61:  *
62:  *   public static void main(String... args) throws Exception {
63:  *     EmbeddedApp.of(s -> s
64:  *       .registryOf(r -> r
65:  *         .add(new ExampleHealthCheck())
66:  *         .add(HealthCheck.of("inline", registry -> // alternative way to implement health checks
67:  *           Promise.value(HealthCheck.Result.unhealthy("FAILED"))
68:  *         ))
69:  *       )
70:  *       .handlers(c -> c
71:  *         .get("health/:name?", new HealthCheckHandler())
72:  *       )
73:  *     ).test(httpClient -> {
74:  *       // Run all health checks
75:  *       String result = httpClient.getText("health");
76:  *       String[] results = result.split("\n");
77:  *       assertEquals(2, results.length);
78:  *       assertEquals("example : HEALTHY", results[0]);
79:  *       assertEquals("inline : UNHEALTHY [FAILED]", results[1]);
80:  *
81:  *       // Run a single health check
82:  *       result = httpClient.getText("health/example");
83:  *       assertEquals("example : HEALTHY", result);
84:  *     });
85:  *   }
86:  * }
87:  * }</pre>
88:  *
89:  * <h3>The output format</h3>
90:  * <p>
91:  * The handler creates a {@link HealthCheckResults} object with the results of running the health checks and {@link Context#render(Object) renders} it.
92:  * Ratpack provides a default renderer for {@link HealthCheckResults} objects, that renders results as plain text one per line with the format:
93:  * <pre>{@code name : HEALTHY|UNHEALTHY [message] [exception]}</pre>
94:  * <p>If any result is unhealthy, a {@code 503} status will be emitted, else {@code 200}.</p>
95:  * <p>
96:  * To change the output format, simply add your own renderer for this type to the registry.
97:  *
98:  * <h3>Concurrency</h3>
99:  * <p>
100:  * The concurrency of the health check execution is managed by a {@link Throttle}.
101:  * By default, an {@link Throttle#unlimited() unlimited throttle} is used.
102:  * A sized throttle can be explicitly given to the constructor.
103:  *
104:  * <h3>Rendering single health checks</h3>
105:  * <p>
106:  * The handler checks for the presence of a {@link Context#getPathBinding() path token} to indicate the name of an individual check to execute.
107:  * By default, the token is named {@value #DEFAULT_NAME_TOKEN}.
108:  * If a path token is present, but indicates the name of a non-existent health check, a {@code 404} {@link Context#clientError(int) client error} will be raised.
109:  *
110:  * @see ratpack.health.HealthCheck
111:  * @see ratpack.health.HealthCheckResults
112:  */
113: public class HealthCheckHandler implements Handler {
114: 
115:   /**
116:    * The default path token name that indicates the individual health check to run.
117:    *
118:    * Value: {@value}
119:    *
120:    * @see #HealthCheckHandler(String, Throttle)
121:    */
122:   public static final String DEFAULT_NAME_TOKEN = "name";
123: 
124:   private static final TypeToken<HealthCheck> HEALTH_CHECK_TYPE_TOKEN = Types.token(HealthCheck.class);
125: 
126:   private final String name;
127:   private final Throttle throttle;
128: 
129:   /**
130:    * Uses the default values of {@link #DEFAULT_NAME_TOKEN} and an unlimited throttle.
131:    *
132:    * @see #HealthCheckHandler(String, Throttle)
133:    */
134:   public HealthCheckHandler() {
135:     this(DEFAULT_NAME_TOKEN, Throttle.unlimited());
136:   }
137: 
138:   /**
139:    * Uses an unlimited throttle and the given name for the health check identifying path token.
140:    *
141:    * @param pathTokenName health check name
142:    * @see #HealthCheckHandler(String, Throttle)
143:    */
144:   public HealthCheckHandler(String pathTokenName) {
145:     this(pathTokenName, Throttle.unlimited());
146:   }
147: 
148:   /**
149:    * Uses the {@link #DEFAULT_NAME_TOKEN} and the given throttle.
150:    *
151:    * @param throttle the throttle for health check execution
152:    * @see #HealthCheckHandler(String, Throttle)
153:    */
154:   public HealthCheckHandler(Throttle throttle) {
155:     this(DEFAULT_NAME_TOKEN, throttle);
156:   }
157: 
158:   /**
159:    * Constructor.
160:    * <p>
161:    * The path token name parameter specifies the name of the path token that, if present, indicates the single health check to execute.
162:    * If this path token is not present, all checks will be run.
163:    * <p>
164:    * The throttle controls the concurrency of health check execution.
165:    * The actual <i>parallelism</i> of the health check executions is ultimately determined by the size of the application event loop in conjunction with the throttle size.
166:    * Generally, an {@link Throttle#unlimited() unlimited throttle} is appropriate unless there are many health checks that are executed frequently as this may degrade the performance of other requests.
167:    * To serialize health check execution, use a throttle of size 1.
168:    *
169:    * @param pathTokenName the name of health check
170:    * @param throttle the throttle for health check execution
171:    */
172:   protected HealthCheckHandler(String pathTokenName, Throttle throttle) {
173:     this.name = pathTokenName;
174:     this.throttle = throttle;
175:   }
176: 
177:   /**
178:    * The throttle for executing health checks.
179:    *
180:    * @return the throttle for executing health checks.
181:    */
182:   public Throttle getThrottle() {
183:     return throttle;
184:   }
185: 
186:   /**
187:    * The name of the path token that may indicate a particular health check to execute.
188:    *
189:    * @return the name of the path token that may indicate a particular health check to execute
190:    */
191:   public String getName() {
192:     return name;
193:   }
194: 
195:   /**
196:    * Renders health checks.
197:    *
198:    * @param ctx the request context
199:    */
200:   @Override
201:   public void handle(Context ctx) {
202:     ctx.getResponse().getHeaders()
203:       .add("Cache-Control", "no-cache, no-store, must-revalidate")
204:       .add("Pragma", "no-cache")
205:       .add("Expires", 0);
206: 
207:     try {
208:       String checkName = ctx.getPathBinding().get(name);
209:       if (checkName != null) {
210:         Optional<HealthCheck> first = ctx.first(HEALTH_CHECK_TYPE_TOKEN, healthCheck -> healthCheck.getName().equals(checkName) ? healthCheck : null);
211:         if (first.isPresent()) {
212:           ctx.render(execute(ctx, Collections.singleton(first.get())));
213:         } else {
214:           ctx.clientError(404);
215:         }
216:       } else {
217:         ctx.render(execute(ctx, ctx.getAll(HEALTH_CHECK_TYPE_TOKEN)));
218:       }
219:     } catch (Exception e) {
220:       ctx.error(e);
221:     }
222:   }
223: 
224:   private Promise<HealthCheck.Result> execute(Registry registry, HealthCheck healthCheck) {
225:     return Promise.wrap(() -> healthCheck.check(registry)).mapError(HealthCheck.Result::unhealthy);
226:   }
227: 
228:   private Promise<HealthCheckResults> execute(Registry registry, Iterable<? extends HealthCheck> healthChecks) {
229:     Iterator<? extends HealthCheck> iterator = healthChecks.iterator();
230:     if (!iterator.hasNext()) {
231:       return Promise.value(new HealthCheckResults(ImmutableSortedMap.of()));
232:     }
233: 
234:     return Promise.<Map<String, HealthCheck.Result>>async(f -> {
235:       AtomicInteger counter = new AtomicInteger();
236:       Map<String, HealthCheck.Result> results = new ConcurrentHashMap<>();
237:       while (iterator.hasNext()) {
238:         counter.incrementAndGet();
239:         HealthCheck healthCheck = iterator.next();
240:         Execution.fork().start(e ->
241:           execute(registry, healthCheck)
242:             .throttled(throttle)
243:             .then(r -> {
244:               results.put(healthCheck.getName(), r);
245:               if (counter.decrementAndGet() == 0 && !iterator.hasNext()) {
246:                 f.success(results);
247:               }
248:             })
249:         );
250:       }
251:     })
252:       .map(ImmutableSortedMap::copyOf)
253:       .map(HealthCheckResults::new);
254:   }
255: }
